update customer
username = #{username}, password = #{password}, name = #{name}, gender = #{gender}, phone = #{phone}, email = #{email}, id_card = #{idCard}, family_phone = #{familyPhone}, photo_url = #{photoUrl}, is_banned = #{isBanned}, update_time = #{updateTime},
where id = #{id}

mapper.select:
SELECT id, username, name, gender, phone, email, id_card, family_phone, photo_url, is_banned, create_time, update_time FROM customer
AND username LIKE CONCAT('%', #{username}, '%')
AND name LIKE CONCAT('%', #{name}, '%')
AND phone LIKE CONCAT('%', #{phone}, '%')
AND is_banned = #{isBanned}
AND create_time >= #{createTimeStart}
AND create_time <= #{createTimeEnd}
ORDER BY create_time DESC
